buggy.uint64_max_to_datetime_coerce:
import pandas as pd
import numpy as np

try:
    result = pd.to_datetime(np.array([np.iinfo(np.uint64).max], dtype=np.uint64), unit='ns', errors='coerce')
    if pd.isna(result[0]):
        probe('uint64_max_to_datetime_coerce', 'NaT')
    else:
        probe('uint64_max_to_datetime_coerce', float(result[0].value))
except Exception as e:
    probe('uint64_max_to_datetime_coerce_exception', str(type(e).__name__))

